package com.gameaggregator.versionservice.api;import jakarta.validation.constraints.*;import java.util.*;import java.util.UUID;public final class VersionDtos{public static final String SEMVER="^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$";private VersionDtos(){}public record Create(@NotNull UUID gameId,@Pattern(regexp=SEMVER)String semanticVersion,@NotBlank String changelog,Map<String,String> compatibility,@NotEmpty Set<String> supportedPlatforms,@Pattern(regexp=SEMVER)String minimumClientVersion){}public record Update(@NotBlank String changelog,Map<String,String> compatibility,@NotEmpty Set<String> supportedPlatforms,@Pattern(regexp=SEMVER)String minimumClientVersion){}public record Status(@Pattern(regexp="DRAFT|PUBLISHED|DEPRECATED")String status){}}